const listScanPackages = `-- name: ListScanPackages :many
SELECT p.id, p.ecosystem, p.name, p.version, p.purl, sp.direct, sp.dev, sp.dependency_path, sp.via, sp.latest_version, sp.deprecated, sp.released_at,
    sp.latest_published_at, sp.maintainers, sp.scorecard, sp.risks, sp.repository_url
FROM scan_packages sp JOIN packages p ON p.id = sp.package_id
WHERE sp.scan_id = ?
ORDER BY sp.direct DESC, p.name
`

type ListScanPackagesRow struct {
	ID                int64            `json:"id"`
	Ecosystem         string           `json:"ecosystem"`
	Name              string           `json:"name"`
	Version           string           `json:"version"`
	Purl              string           `json:"purl"`
	Direct            bool             `json:"direct"`
	Dev               bool             `json:"dev"`
	DependencyPath    sqltypes.Strings `json:"dependency_path"`
	Via               sqltypes.Strings `json:"via"`
	LatestVersion     string           `json:"latest_version"`
	Deprecated        bool             `json:"deprecated"`
	ReleasedAt        *time.Time       `json:"released_at"`
	LatestPublishedAt *time.Time       `json:"latest_published_at"`
	Maintainers       *int32           `json:"maintainers"`
	Scorecard         *float64         `json:"scorecard"`
	Risks             sqltypes.Strings `json:"risks"`
	RepositoryUrl     string           `json:"repository_url"`
}

func (q *Queries) ListScanPackages(ctx context.Context, scanID int64) ([]ListScanPackagesRow, error) {
	rows, err := q.db.QueryContext(ctx, listScanPackages, scanID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListScanPackagesRow{}
	for rows.Next() {
		var i ListScanPackagesRow
		if err := rows.Scan(
			&i.ID,
			&i.Ecosystem,
			&i.Name,
			&i.Version,
			&i.Purl,
			&i.Direct,
			&i.Dev,
			&i.DependencyPath,
			&i.Via,
			&i.LatestVersion,
			&i.Deprecated,
			&i.ReleasedAt,
			&i.LatestPublishedAt,
			&i.Maintainers,
			&i.Scorecard,
			&i.Risks,
			&i.RepositoryUrl,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const markStaleScansFailed = `-- name: MarkStaleScansFailed :execrows
UPDATE scans SET status = 'failed', finished_at = strftime('%Y-%m-%d %H:%M:%f+00:00', 'now'), error = 'scan timed out'
WHERE status IN ('queued', 'running') AND created_at < ?
`

// Scans stuck in running state (worker crash) are failed after the given cutoff.
func (q *Queries) MarkStaleScansFailed(ctx context.Context, createdAt time.Time) (int64, error) {
	result, err := q.db.ExecContext(ctx, markStaleScansFailed, createdAt)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const refreshVulnEnrichment = `-- name: RefreshVulnEnrichment :execrows
UPDATE vulnerabilities SET
    in_kev = EXISTS (SELECT 1 FROM kev_entries k WHERE k.cve_id IN (
        SELECT vulnerabilities.id UNION ALL SELECT value FROM json_each(vulnerabilities.aliases))),
    epss_score = (SELECT max(e.score) FROM epss_scores e WHERE e.cve_id IN (
        SELECT vulnerabilities.id UNION ALL SELECT value FROM json_each(vulnerabilities.aliases)))
`

// Propagate fresh KEV/EPSS data to vulnerabilities.
// IN (id + aliases) keeps primary key lookups; an OR would scan epss_scores for each vulnerability.
func (q *Queries) RefreshVulnEnrichment(ctx context.Context) (int64, error) {
	result, err := q.db.ExecContext(ctx, refreshVulnEnrichment)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

